interface AuditEntry {
  readonly id: string;
  readonly timestamp: Date;
  message: string;
}

const entry: AuditEntry = {
  id: "a-1",
  timestamp: new Date(),
  message: "login",
};

// entry.id = "a-2";     // Error: cannot assign to readonly
entry.message = "logout"; // OK

function sum(nums: readonly number[]): number {
  // nums.push(1); // Error: push does not exist on readonly array
  return nums.reduce((a, b) => a + b, 0);
}

type Point = { x: number; y: number };
function printPoint(p: Readonly<Point>): void {
  console.log(p.x, p.y);
}

const coords: number[] = [1, 2, 3];
sum(coords); // mutable array assignable to readonly

const DIRECTIONS = ["north", "east", "south", "west"] as const;
// type: readonly ["north", "east", "south", "west"]

type Direction = typeof DIRECTIONS[number];
// "north" | "east" | "south" | "west"

function go(dir: Direction): void {
  console.log(dir);
}

type State = Readonly<{ user: { name: string } }>;

const state: State = { user: { name: "Ada" } };
// state.user = { name: "Bob" }; // Error: readonly property
state.user.name = "Bob";         // OK at compile time — nested not readonly!

// Deep immutability needs recursive Readonly or a library
